def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id in opponents_status:
        opp = opponents_status[opp_id]
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 2:
            return min(budget, 63)
        if supply >= 22:
            return min(budget, 18)
        return min(budget, 28)

    prev_bids = []
    distress_count = 0
    rich_count = 0
    total_req = WATER_REQ

    for opp in alive_opponents:
        total_req += opp.get('water_requirement', WATER_REQ)
        if opp.get('budget', 0) >= DAILY_SALARY * 4:
            rich_count += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
            distress_count += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))
            status = prev.get('status')
            if status in ['lost', 'thirsty', 'error']:
                distress_count += 1

    expected_competition = float(total_req) / float(max(supply, 1))

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
    else:
        highest_prev = 0
        avg_prev = 0

    if hp <= 2 or no_water_days >= 2:
        bid = max(60, highest_prev + 2)
    elif hp <= 4 or no_water_days >= 1:
        bid = max(48, avg_prev + 3)
    else:
        if supply >= 23:
            bid = 20
        elif supply >= 20:
            bid = 28
        elif supply >= 17:
            bid = 36
        else:
            bid = 44

        if expected_competition > 2.0:
            bid += 8
        elif expected_competition > 1.5:
            bid += 4

        if highest_prev >= 60:
            bid = max(bid, highest_prev - 8 if hp > 4 else highest_prev + 1)
        elif highest_prev >= 45:
            bid = max(bid, highest_prev + 2)
        elif highest_prev > 0:
            bid = max(bid, avg_prev + 2)

    bid += min(distress_count, 3) * 2
    bid += min(rich_count, 2) * 2

    if budget < DAILY_SALARY * 2 and hp > 4 and no_water_days == 0:
        bid *= 0.8

    if supply >= 24 and hp > 4 and no_water_days == 0:
        bid *= 0.85

    bid = max(0, min(budget, bid))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = day_context['day']

    alive_opps = []
    for opp in opponents_status.values():
        if opp.get('alive', True):
            alive_opps.append(opp)

    if not alive_opps:
        return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Extract yesterday bids from previous_trace
    yesterday_bids = []
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # Base bid intensity from yesterday behavior
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # If opponents were strongly pressuring, we defend more.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                bid = DAILY_SALARY * 0.32
            else:
                bid = DAILY_SALARY * 0.9
        else:
            # If they were cautious, we bid enough to secure while not overpaying.
            # Increase slightly above their max to gain allocation.
            bid = max(DAILY_SALARY * 0.5, highest_prev_bid + 1.5)
    else:
        # No trace info: bid based on our health.
        if my_status['hp'] <= 2:
            bid = DAILY_SALARY * 0.85
        else:
            bid = DAILY_SALARY * 0.55

    # Supply-aware adjustment: tighter supply -> slightly higher bid.
    # supply is in [15,25]; map to a multiplier in [~1.1, ~0.9]
    tightness = (25.0 - supply) / 10.0  # 0..1
    bid *= (1.0 + 0.2 * tightness)

    # Ensure we never bid more than our budget.
    bid = min(float(my_status['budget']), float(bid))

    # If we are at risk (many no-water days), raise bid.
    no_water_days = float(my_status.get('no_water_days', 0))
    if no_water_days >= 2:
        bid = min(float(my_status['budget']), max(bid, DAILY_SALARY * 0.75))

    # Final safety clamp
    if bid < 0:
        bid = 0.0
    return bid

